import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import drop_crate_globals as dcg

ISLAND = (
    "/* automatically generated by rust-bindgen 0.73.2 */\n"
    'unsafe extern "C" {\n    pub static mut g_hinstExe: HINSTANCE;\n}\n'
    'unsafe extern "C" {\n    #[link_name = "\\u{1}__pobjMapEntryFirst"]\n'
    "    pub static mut ATL___pobjMapEntryFirst: *mut ATL__ATL_OBJMAP_ENTRY;\n}\n"
    'unsafe extern "C" {\n    pub static mut g_private: BOOL;\n}\n'
)


def test_a_crate_defined_global_becomes_a_use_and_an_import_stays(tmp_path):
    src = tmp_path / "src"
    (src / "mspaint").mkdir(parents=True)
    (src / "lib.rs").write_text("pub mod types;\npub mod mspaint {\n    pub mod main_cpp_h;\n}\n")
    (src / "types.rs").write_text(ISLAND)
    (src / "mspaint" / "main_cpp_h.rs").write_text(
        "#[no_mangle]\npub static mut g_hinstExe: HINSTANCE = core::ptr::null_mut();\n"
        "static mut g_private: BOOL = 0;\nfn f() {\n    static LOCAL: u32 = 0;\n}\n"
    )
    out, n, kept = dcg.rewrite(ISLAND, dcg.crate_globals(src))
    assert n == 1
    assert "pub use crate::mspaint::main_cpp_h::g_hinstExe;\n" in out
    assert "ATL___pobjMapEntryFirst" in out  # imported, not defined here
    assert "pub static mut g_private" in out and kept  # not pub: a `use` would be E0364
